/**
 * The firms, and the shape of the assessments they are reported to set.
 *
 * READ THIS BEFORE ADDING A FIRM.
 *
 * Everything here is a *format reconstruction*: how many questions, how long, of what type, under
 * what rules. It is assembled from firms' own published descriptions of their process and from
 * widely repeated candidate accounts. None of it is any firm's question bank, none of it is
 * confidential, and the questions a candidate sees here are generated by this repo's own
 * generators. The UI says so on every screen, and `sourcing` on each assessment says where that
 * particular shape comes from.
 *
 * Two honesty rules, because a trainer that overstates its fidelity is worse than none:
 *
 * 1. `reportedPassMark` is set only where candidates consistently report the same figure. A made-up
 *    cutoff would have people walking away from a firm on the strength of a number we invented, so
 *    where it is not known it is simply absent and the UI says the mark is not published.
 * 2. Where a firm's assessment includes something this app genuinely cannot simulate — a
 *    code-judge round, a live interactive trading game — it is named in `rules` as not covered
 *    rather than replaced with something easier that pretends to be it.
 *
 * Formats change. This is a training aid, not an oracle.
 */
import type { Assessment, Firm, QuestionKind, Section } from "./types";

let counter = 0;

function sec(
  kind: QuestionKind,
  name: string,
  count: number,
  seconds: number,
  level: number,
  brief: string,
): Section {
  return { id: `s${++counter}`, name, kind, count, seconds, level, brief };
}

interface Draft {
  id: string;
  name: string;
  format: string;
  sections: Section[];
  rules: string[];
  sourcing: string;
  reportedPassMark?: number;
}

function firm(
  id: string,
  name: string,
  blurb: string,
  process: string[],
  drafts: Draft[],
): Firm {
  return {
    id,
    name,
    blurb,
    process,
    assessments: drafts.map((d) => ({ ...d, firmId: id })),
  };
}

const NOT_SIMULATED = (what: string) =>
  `${what} is part of the real process and is not simulated here — this app grades deterministic maths in your browser, and faking a ${what.toLowerCase()} would train the wrong thing.`;

